INSERT INTO sys_ai_prompt (id, prompt_code, prompt_name, content, version_no, enabled, remark, created_at, updated_at) VALUES ('00000000000000000000000000000660', 'ANALYSIS_SUGGEST', '需求分析建议', '你是 CIM 制造系统的需求分析助手。根据需求标题、现状、期望和相似需求清单，给出三问结论：是否已存在、是否有必要、影响哪些系统；再给出实现建议与 ROI 估算。只输出 JSON，不要解释文字。', 1, 1, '改提示词请升 version_no，否则同一单隔周重跑结论不同无法解释', TO_TIMESTAMP('2026-11-02 09:00:00','YYYY-MM-DD HH24:MI:SS'), TO_TIMESTAMP('2026-11-02 09:00:00','YYYY-MM-DD HH24:MI:SS'));
INSERT INTO sys_ai_prompt (id, prompt_code, prompt_name, content, version_no, enabled, remark, created_at, updated_at) VALUES ('00000000000000000000000000000661', 'CASE_GENERATE', '测试用例生成', '根据锁定后的验收标准，逐条生成测试用例，每条用例必须标注对应的验收标准序号。优先覆盖硬性指标、边界条件、外部交互、权限安全。单需求不超过 15 条。重点关注项必须写明原因。只输出 JSON。', 1, 1, '改提示词请升 version_no，否则同一单隔周重跑结论不同无法解释', TO_TIMESTAMP('2026-11-02 09:00:00','YYYY-MM-DD HH24:MI:SS'), TO_TIMESTAMP('2026-11-02 09:00:00','YYYY-MM-DD HH24:MI:SS'));
